import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression
from sklearn.feature_selection import mutual_info_classif
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Identify potential drivers using correlation with outcome
    drivers = []
    columns = []
    products = []
    loadings = {}

    # Check for strong correlations with outcome
    for i, fid in enumerate(feats.ids):
        if feats.types[i] in ('expression', 'copy_number', 'clinical'):
            corr = np.corrcoef(feats.x[:, i], feats.y)[0, 1]
            if abs(corr) > 0.1:
                columns.append(fid)
                loadings[fid] = corr

    # If no strong correlations, return empty design
    if not columns:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Remove near-duplicates based on correlation matrix
    corr_matrix = np.corrcoef(feats.x[:, [feats.column(fid) for fid in columns]])
    to_remove = set()
    for i in range(len(columns)):
        for j in range(i+1, len(columns)):
            if abs(corr_matrix[i, j]) > 0.6:
                to_remove.add(columns[j])

    columns = [fid for fid in columns if fid not in to_remove]

    # Select top features by correlation strength
    sorted_features = sorted(columns, key=lambda f: abs(loadings[f]), reverse=True)
    drivers = sorted_features[:MAX_DRIVERS]

    # Add interaction terms between top drivers
    for i in range(min(2, len(drivers))):
        for j in range(i+1, min(3, len(drivers))):
            products.append((drivers[i], drivers[j]))

    return Design(drivers=tuple(drivers), columns=tuple(columns), products=tuple(products), loadings=loadings)

